    val description: String? = null,
    val orderedQty: BigDecimal? = null,
    val unitCost: BigDecimal? = null,
    val taxRatePct: BigDecimal? = null,
    val workOrderId: String? = null,
    val notes: String? = null,
    /** Nullable fields to set to NULL (a field cannot be both set and cleared). */
    val clear: Set<Clear> = emptySet(),
) : V2CommandPayload {
    enum class Clear(override val wire: String) : V2WireEnum {
        TAX_RATE_PCT("tax_rate_pct"),
        WORK_ORDER_ID("work_order_id"),
        NOTES("notes"),
    }

    override fun toJson(): JsonObject {
        val set = V2PayloadJson.objectOf("description" to description, "ordered_qty" to orderedQty, "unit_cost" to unitCost, "tax_rate_pct" to taxRatePct, "work_order_id" to workOrderId, "notes" to notes)
        val clearSet = clear.mapTo(mutableSetOf()) { it.wire }
        require(set.keys.none { it in clearSet }) { "a field cannot be both set and cleared" }
        require(set.isNotEmpty() || clear.isNotEmpty()) { "an update must change something" }
        return JsonObject(mapOf("id" to JsonPrimitive(id), "set" to set, "clear" to JsonArray(clearSet.sorted().map(::JsonPrimitive))))
    }

    override val commandName: String get() = "stock.purchase_order_lines.update"
    override val commandEntityType: String get() = "purchase_order_lines"
    override val commandEntityKey: String get() = id
    override val commandKind: V2CommandKind get() = V2CommandKind.UPDATE
    override val requiresBaseVersion: Boolean get() = true
}

